function rateLimited(userId:string){const current=Date.now(),existing=rateWindows.get(userId);if(!existing||current>=existing.resetAt){rateWindows.set(userId,{count:1,resetAt:current+60_000});return false}existing.count+=1;return existing.count>12}
function searchable(value:unknown){return textValue(value,5000).toLowerCase()}
function queryTerms(query:string){return [...new Set(query.toLowerCase().match(/[a-z0-9_/-]{3,}/g)||[])].filter(term=>!['what','when','where','which','would','could','should','about','this','that','with','from','have'].includes(term)).slice(0,40)}
function matches(record:any,terms:string[]){const haystack=searchable(Object.values(record||{}).flat().join(' '));return terms.some(term=>haystack.includes(term))}
function slug(value:unknown){return searchable(value).replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,80)}
function usagePrice(model:string){return model.includes('sol')?{input:5,cachedInput:.5,output:30,currency:'USD',unit:'per_million_tokens'}:{input:2.5,cachedInput:.25,output:15,currency:'USD',unit:'per_million_tokens'}}
function usageValues(usage:any){const input=Math.max(0,Number(usage?.input_tokens)||0),cached=Math.min(input,Math.max(0,Number(usage?.input_tokens_details?.cached_tokens)||0)),output=Math.max(0,Number(usage?.output_tokens)||0);return {input,cached,output}}
function usageCost(usage:any,price:any){const value=usageValues(usage);return {...value,cost:((value.input-value.cached)*price.input+value.cached*price.cachedInput+value.output*price.output)/1_000_000}}
function normalizedId(value:unknown){return slug(value)}
function versionMap(sourceVersions:any){const versions=new Map<string,number>();for(const record of list(sourceVersions?.standardAbilities,1000)){const id=normalizedId(record?.abilityId),version=Number(record?.version);if(id&&version>0)versions.set(id,version)}return versions}
function evaluatePrecedentCompatibility(precedent:any,current:any){
  let level=['EXACT','STRONG','PARTIAL','INCOMPATIBLE'].includes(precedent?.applicability)?precedent.applicability:'PARTIAL';const reasons:string[]=[];
  if(precedent?.scope!=='GLOBAL')return {...precedent,applicability:level,compatibility_reasons:[...(Object.entries(precedent?.compatibility_reasons||{}).filter(([,value])=>value).map(([key])=>key)),...reasons]};
  if(list(precedent?.role_ids,100).length){level='INCOMPATIBLE';reasons.push('Role-specific precedents cannot be generalized across games.')}
  const requiredStatuses=list(precedent?.status_types,100).map(normalizedId),currentStatuses=new Set(list(current?.statusTypes,100).map(normalizedId));if(requiredStatuses.some((status:string)=>status&&!currentStatuses.has(status))&&level!=='INCOMPATIBLE'){level='PARTIAL';reasons.push('Important live-status conditions differ from the historical ruling.')}
  const currentConcepts=new Map(list(current?.mappings,1000).flatMap((mapping:any)=>[[String(mapping?.global_concept_id||''),mapping.compatibility_level],[String(mapping?.global_ability_concepts?.concept_key||''),mapping.compatibility_level]]));const precedentConcepts=list(precedent?.global_concept_ids,100).map(String);
  if(precedentConcepts.length){const mapped=precedentConcepts.filter((concept:string)=>currentConcepts.has(concept)),mappedLevels=mapped.map((concept:string)=>currentConcepts.get(concept));if(!mapped.length&&level!=='INCOMPATIBLE'){level='PARTIAL';reasons.push('No approved current-game ability mapping confirms the same global mechanical concept.')}if(mappedLevels.includes('INCOMPATIBLE')){level='INCOMPATIBLE';reasons.push('An approved ability mapping marks the mechanics incompatible.')}else if(mappedLevels.includes('PARTIAL')&&level!=='INCOMPATIBLE'){level='PARTIAL';reasons.push('The approved ability mapping is only partially compatible.')}}
  const historical=versionMap(precedent?.rule_versions),active=versionMap(current?.sourceVersions);for(const [abilityId,oldVersion] of historical){const newVersion=active.get(abilityId);if(newVersion&&newVersion!==oldVersion&&level!=='INCOMPATIBLE'){level='PARTIAL';reasons.push(`Ability ${abilityId} changed from version ${oldVersion} to ${newVersion}; the precedent may be outdated.`)}}
  if(!reasons.length)reasons.push('Mechanical signature and recorded conditions remain compatible with the available current-game context.');return {...precedent,applicability:level,compatibility_reasons:reasons};
}

function buildFocusedGameContext(document:any,query:string,task:string,liveState:any,session:any,phaseContext:any){
  const game=document?.game||{},data=document?.data||{},abilities=list(data.abilities,1000),roles=list(data.roles,1000),factions=list(data.factions,300),players=list(data.players,1000),currentPhase=list(phaseContext?.phases,200).find((phase:any)=>String(phase.id)===String(phaseContext?.current_phase_id))||null,actions=session?list(session.submitted_actions,1000):currentPhase?list(currentPhase.action_queue,1000):list(data.actions,1000),rules=list(data.rules,1000).filter((rule:any)=>rule.enabled!==false),history=list(data.history,500),terms=queryTerms(query);
  const roleById=new Map(roles.map((role:any)=>[role.id,role])),abilityById=new Map(abilities.map((ability:any)=>[ability.id,ability]));
  const selectedPlayerIds=new Set(players.filter((player:any)=>matches(player,terms)).map((player:any)=>player.id));
  const selectedRoleIds=new Set(roles.filter((role:any)=>matches(role,terms)).map((role:any)=>role.id));
  players.filter((player:any)=>selectedPlayerIds.has(player.id)).forEach((player:any)=>selectedRoleIds.add(player.roleId));
  if(task==='resolve_actions')actions.forEach((action:any)=>{selectedPlayerIds.add(action.sourcePlayerId||action.actorId);for(const targetId of list(action.targetIds,100))selectedPlayerIds.add(targetId);if(action.targetId)selectedPlayerIds.add(action.targetId)});
  const activeEffects=list(liveState?.activeEffects,1000),pendingEffects=list(liveState?.pendingEffects,1000),statusHistory=list(liveState?.recentHistory,250);
  for(const effect of [...activeEffects,...pendingEffects])if(matches(effect,terms)||selectedPlayerIds.has(effect.player_id))selectedPlayerIds.add(effect.player_id);
  players.filter((player:any)=>selectedPlayerIds.has(player.id)).forEach((player:any)=>selectedRoleIds.add(player.roleId));
  const selectedAbilityIds=new Set(abilities.filter((ability:any)=>matches(ability,terms)).map((ability:any)=>ability.id));
  roles.filter((role:any)=>selectedRoleIds.has(role.id)).forEach((role:any)=>{if(role.activeAbilityId)selectedAbilityIds.add(role.activeAbilityId);if(role.passiveAbilityId)selectedAbilityIds.add(role.passiveAbilityId);for(const ability of abilities)if(list(role.tags,100).some((tag:any)=>searchable(tag)===searchable(ability.name)))selectedAbilityIds.add(ability.id)});
  const relevantRules=rules.filter((rule:any)=>matches(rule,terms));
  return {
    game:{id:textValue(game.id,100),name:textValue(game.name,120),theme:textValue(game.theme,200),description:textValue(game.description),status:textValue(game.status,40),currentDay:Number(game.currentDay)||0,currentPhase:game.currentPhase==='Night'?'Night':'Day',notes:textValue(game.notes)},settings:data.settings||{},basicRolePolicy:{roleType:'BASIC',ownedAbilities:[],meaning:'Intentionally no role abilities; faction, voting, participation, targeting, and statuses still apply.',safety:'Never classify missing ability data as Basic without explicit GM or document evidence.',randomization:'Only the server assignment RPC may randomize role slots.'},
    indexes:{factions:factions.map((item:any)=>({id:item.id,name:item.name,class:item.class})),roles:roles.map((item:any)=>({id:item.id,name:item.name,factionId:item.factionId,roleType:item.roleType||'STANDARD',slotCount:Math.max(1,Number(item.slotCount)||1),abilityNames:list(item.tags,100)})),abilities:abilities.map((item:any)=>({id:item.id,name:item.name,category:item.category})),players:players.map((item:any)=>({id:item.id,name:item.name,alive:Boolean(item.alive),roleId:item.roleId,currentFactionId:item.currentFactionId||item.factionId||''})),rules:rules.map((item:any)=>({id:item.id,title:item.title,category:item.category}))},
    relevant:{roles:roles.filter((item:any)=>selectedRoleIds.has(item.id)).slice(0,80),abilities:abilities.filter((item:any)=>selectedAbilityIds.has(item.id)).slice(0,100),players:players.filter((item:any)=>selectedPlayerIds.has(item.id)).slice(0,100),rules:(relevantRules.length?relevantRules:rules.slice(0,20)),history:history.filter((entry:any)=>matches(entry,terms)).slice(-20)},
    livePlayerState:{authority:'LIVE_GAME_DATABASE',activeEffects:activeEffects.map((effect:any)=>({...effect,playerName:players.find((player:any)=>player.id===effect.player_id)?.name||'',sourcePlayerName:players.find((player:any)=>player.id===effect.source_player_id)?.name||''})),pendingEffects:pendingEffects.map((effect:any)=>({...effect,playerName:players.find((player:any)=>player.id===effect.player_id)?.name||'',sourcePlayerName:players.find((player:any)=>player.id===effect.source_player_id)?.name||''})),recentStatusHistory:statusHistory.map((event:any)=>({statusId:event.status_id,playerId:event.player_id,playerName:players.find((player:any)=>player.id===event.player_id)?.name||'',action:event.status_action,reason:event.reason,previousEffect:event.previous_effect,nextEffect:event.next_effect,createdAt:event.created_at}))},
    queuedActions:actions.map((action:any)=>{const actorId=action.sourcePlayerId||action.actorId,targetIds=list(action.targetIds,100).length?list(action.targetIds,100):[action.targetId].filter(Boolean);return {...action,actorName:players.find((p:any)=>p.id===actorId)?.name||'',targetName:targetIds.map((targetId:any)=>players.find((p:any)=>p.id===targetId)?.name||targetId).join(', '),roleName:(roleById.get(players.find((p:any)=>p.id===actorId)?.roleId) as any)?.name||'',abilityName:(abilityById.get(action.abilityId) as any)?.name||''}}),
    phaseController:phaseContext?{gameStatus:phaseContext.game_status,currentPhaseId:phaseContext.current_phase_id,currentPhase,currentAdvancePreview:phaseContext.preview,phaseHistory:list(phaseContext.phases,200),phaseEvents:list(phaseContext.events,500),phaseSessions:list(phaseContext.sessions,200)}:null,
    resolutionSession:session?{id:session.id,phaseId:session.phase_id,cycle:session.cycle,phase:session.phase,status:session.status,sourceGameVersion:session.source_game_version,sourcePhaseVersion:session.source_phase_version,lockVersion:session.lock_version,preResolutionState:session.pre_resolution_state,sourceVersions:session.source_versions}:null
  };
}

function sourceRecord(id:string,kind:string,title:string,version:string,locator:string,excerpt:string,metadata:any={}){return {id,kind,title,version,locator,excerpt:textValue(excerpt,1200),...metadata}}

function documentIndexes(document:any){const game=document?.game||{},data=document?.data||{};return {games:[{id:game.id,name:game.name,theme:game.theme}],players:list(data.players,1000),roles:list(data.roles,1000),abilities:list(data.abilities,1000),factions:list(data.factions,300),rules:list(data.rules,1000)}}
